{
  "name": "GRBL 三轴电动位移台",
  "name_en": "GRBL-controlled XYZ motorized stage",
  "manufacturer": "",
  "description": "这是一类由 GRBL 运动控制器驱动的三轴电动位移平台，通常采用步进电机实现 X、Y、Z 方向移动，并支持回零与位置查询。在实验室中常用于显微镜样品定位、自动扫描、对焦位移和小型自动化运动控制。",
  "description_en": "This is a three-axis motorized positioning stage driven by a GRBL motion controller, typically using stepper motors for X, Y, and Z travel with homing and position readback. In laboratories it is commonly used for microscope sample positioning, automated scanning, focus translation, and small-scale motion automation.",
  "tag_hints": [
    "GRBL motion control",
    "XYZ translation stage",
    "G-code positioning",
    "stepper motor stage",
    "microscope sample positioning",
    "automated scanning"
  ],
  "actions": [
    {
      "action_name": "auto-write",
      "description": "向 GRBL 运动控制器写入原始命令。",
      "description_en": "Write a raw command to the GRBL motion controller."
    },
    {
      "action_name": "auto-send_wake_up",
      "description": "唤醒 GRBL 控制器并建立可用通信状态。",
      "description_en": "Wake up the GRBL controller and bring it into a communicable state."
    },
    {
      "action_name": "auto-send_gcode_command",
      "description": "向位移台发送一条 G 代码运动或控制命令，可选择等待执行完成。",
      "description_en": "Send a G-code motion or control command to the stage, optionally waiting for completion."
    },
    {
      "action_name": "auto-send_gcode_command_inThread",
      "description": "以异步方式向位移台发送一条 G 代码命令。",
      "description_en": "Send a G-code command to the stage asynchronously."
    },
    {
      "action_name": "auto-wait_for_movement_completion",
      "description": "等待当前位移运动完成。",
      "description_en": "Wait for the current motion to finish."
    },
    {
      "action_name": "auto-remove_comment",
      "description": "移除 G 代码命令中的注释内容。",
      "description_en": "Remove comment text from a G-code command."
    },
    {
      "action_name": "auto-remove_eol_chars",
      "description": "移除命令字符串中的行尾字符。",
      "description_en": "Remove end-of-line characters from a command string."
    },
    {
      "action_name": "auto-move",
      "description": "控制位移台进行 X、Y、Z 轴绝对或相对移动。",
      "description_en": "Move the stage in X, Y, and Z using absolute or relative positioning."
    },
    {
      "action_name": "auto-home",
      "description": "使位移台各轴执行回零。",
      "description_en": "Home the stage axes."
    },
    {
      "action_name": "auto-get_position",
      "description": "获取位移台当前坐标位置。",
      "description_en": "Get the current position of the stage."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与位移台控制器的连接。",
      "description_en": "Close the connection to the stage controller."
    }
  ]
}

